-- 二、新增主题文章（newcomer）
-- ───────────────────────────

-- id=25 快递与生活服务指南
INSERT IGNORE INTO contents (id, school_id, category, sub_category, title, summary, cover_url, resource_url, resource_name, body, body_type, sort_order, status, view_count, created_by) VALUES
(25, 1, 'newcomer', 'express', '快递与生活服务指南', '网购寄快递地址怎么写 + 校园生活服务一图通', '/campus/uploads/resources/covers/cover-25.jpg', NULL, '', '<h2>网购/寄快递地址这样填</h2><p>校区地址：成都市龙泉驿区驿都西路 4111 号，邮编 610101。</p><p>填收货地址时写：四川省成都市龙泉驿区驿都西路 4111 号 + 你的楼栋宿舍（如 X 苑 X 栋 XXX 室），快递员和驿站好分拣。</p><h2>快递到哪取</h2><p>校内有快递服务点/驿站统一代收，包裹到后一般会收到取件码短信，凭取件码到驿站自取（大件或需要验证的件带好证件）。具体点位分布和营业时间以驿站短信和现场为准。</p><ul><li>包裹到了别拖太久，驿站一般有免费存放期限，超时要收费或退回</li><li>生鲜、药品等时效件，到货当天尽快取</li><li>开学季包裹多，驿站排队是常态，错开中午取件高峰</li></ul><h2>寄快递</h2><p>寄件直接在驿站/快递点下单，或叫上门取件。寄之前问清禁寄品（充电宝、液体等限制以快递公司规定为准）。</p><h2>校园生活服务速查</h2><ul><li>校园卡：充值、挂失、补办渠道以学校官方指引为准，报到服务点可咨询</li><li>宿舍报修：值班室登记或后勤线上渠道（见宿舍指南）</li><li>打印复印：图书馆、教学楼和校园商业区一般都有打印点</li><li>超市购物：校内超市买日用品，报到高峰建议错峰</li><li>校医院：小病直接去，带上校园卡/医保信息</li></ul><h2>一个提醒</h2><p>报到季是推销高发期，上门推销电话卡、学习资料、健身卡的一律先说不，去官方渠道办。地址信息也只给正经快递，别在路边小摊随便填个人信息。</p>', 'html', 12, 'published', 0, 0);

-- id=26 新生安全防骗指南
INSERT IGNORE INTO contents (id, school_id, category, sub_category, title, summary, cover_url, resource_url, resource_name, body, body_type, sort_order, status, view_count, created_by) VALUES
(26, 1, 'newcomer', 'safety', '新生安全防骗指南', '开学季骗子最多，这篇帮你避坑', '/campus/uploads/resources/covers/cover-26.jpg', NULL, '', '<h2>为什么开学季骗子多</h2><p>新生刚到校，不熟悉环境、脸皮薄、不敢拒绝，是诈骗和推销的重点目标。记住一条铁律：<strong>凡是让你先交钱、给验证码、转账的，99% 是骗子。</strong></p><h2>常见骗术一：冒充老师/学长收费</h2><p>有人自称辅导员、老师、学长学姐，在群里或上门收"教材费、培训费、押金"——先核实！学费只走学校官方渠道，任何私人收款码都别扫。真正的老师不会私下收现金。</p><h2>常见骗术二：上门推销</h2><p>宿舍敲门推销电话卡、英语报、学习资料、化妆品、健身卡——礼貌拒绝，别让进门。电话卡校园网去官方服务点办，比推销的便宜还靠谱。</p><h2>常见骗术三：兼职刷单</h2><p>"动动手指日入几百"的刷单返利全是骗局，前期返小利钓你，后面本金直接卷走。正规兼职不让你先交押金、培训费。</p><h2>常见骗术四：冒充客服退款</h2><p>"你买的商品有质量问题要退款""快递丢失双倍赔偿"——让你点链接、输银行卡验证码的都是骗子。真退款走官方 App，不点短信链接。</p><h2>常见骗术五：校园贷/注销校园贷</h2><p>任何形式的校园贷都不要碰；"帮你注销校园贷账户否则影响征信"是经典骗局，直接挂电话。缺钱找学校资助体系（奖助学金、勤工助学），别碰网贷。</p><h2>账号与两卡安全</h2><ul><li>银行卡、身份证、手机卡不借、不租、不卖，不帮人"走账"——那是帮人洗钱，要担刑责</li><li>账号密码、验证码谁要都不给，官方也不会找你要</li><li>手机设好锁屏密码，支付软件开小额免密要谨慎</li></ul><h2>人身与财物安全</h2><ul><li>贵重物品锁柜子，出门锁门</li><li>晚上尽量结伴，走亮的路；校外聚餐别喝多</li><li>遇到纠缠、威胁，直接找辅导员/宿管/保卫处，紧急情况打 110</li></ul><h2>被骗了怎么办</h2><p>别因为丢脸瞒着！第一时间告诉辅导员，尽快报警（110），保留聊天记录和转账凭证。早一分钟处理，追回的概率大一分。</p>', 'html', 13, 'published', 0, 0);

-- id=27 开学时间线：一图看懂第一学期
INSERT IGNORE INTO contents (id, school_id, category, sub_category, title, summary, cover_url, resource_url, resource_name, body, body_type, sort_order, status, view_count, created_by) VALUES
(27, 1, 'newcomer', 'timeline', '开学时间线：第一学期关键节点', '从报到到期末，心里有张时间表', '/campus/uploads/resources/covers/cover-27.jpg', NULL, '', '<h2>8 月底：报到与开学</h2><ul><li>8 月 28-29 日：新生集中报到（流程见"新生报到流程"篇）</li><li>8 月 31 日：开学典礼，之后正式行课</li></ul><p>刚开学两周是适应期：认路、认识室友同学、摸清食堂作息，别急着把自己安排满。</p><h2>9 月：入学教育与社团招新</h2><ul><li>各院系入学教育、班会、领教材陆续进行</li><li>补考/重修考试一般在 9 月上旬（老生补考，新生可忽略）</li><li>社团集中招新通常在这段时间开始，留意公告</li></ul><p>学习节奏上，第一学期课程以公共课+专业基础课为主，认真听讲做笔记，期中的时候会轻松很多。</p><h2>9-10 月：第一个假期</h2><ul><li>中秋节（9 月下旬）、国庆节（10 月初）连休，可以回家或周边转转</li><li>假期前后注意往返车票提前买</li></ul><h2>11 月：期中与重修</h2><ul><li>部分课程期中考试/阶段测验</li><li>自主重修考试一般在 11 月中旬（不挂科就和你无关）</li></ul><h2>12 月：四六级与期末冲刺</h2><ul><li>大学英语四六级考试一般在 12 月中旬，报名的同学提前刷题</li><li>进入期末复习月，平时分稳住、重点复习专业课</li></ul><h2>1 月：军训与期末</h2><ul><li>新生期末统考在学期末考试周</li><li>新生军训按校历安排在本学期末（1 月）进行，具体以通知为准</li><li>考完军训完就放寒假啦，回家的票记得提前抢</li></ul><p>以上时间节点依据本学期校历整理，若有调整以学校最新通知为准。想随时查考试安排、课表，用 CampusLink 扫码同步最方便。</p>', 'html', 14, 'published', 0, 0);
